46	// MARK: - Client
47	
48	final class BridgeClient: NSObject {
49	    let credentials: PairingCredentials
50	    weak var delegate: BridgeClientDelegate?
51	
52	    private var task: URLSessionWebSocketTask?
53	    private var session: URLSession?
54	    private var completions: [String: ([String: Any]) -> Void] = [:]
55	    private var reconnectTask: Task<Void, Never>?
56	    private var shouldReconnect = true
57	    private var backoff: TimeInterval = 1
58	
59	    init(credentials: PairingCredentials) {
60	        self.credentials = credentials
61	    }
62	
63	    // MARK: - Public API
64	
65	    func connect() {
66	        shouldReconnect = true
67	        startConnection()
68	    }
69	
70	    func disconnect() {
71	        shouldReconnect = false
72	        reconnectTask?.cancel()
73	        task?.cancel(with: .normalClosure, reason: nil)
74	        task = nil
75	    }
76	
77	    func send(
78	        method: String,
79	        params: [String: Any],
80	        completion: (([String: Any]) -> Void)? = nil
81	    ) {
82	        let id = UUID().uuidString
83	        let payload: [String: Any] = ["id": id, "method": method, "params": params]
84	
85	        if let completion {
86	            completions[id] = completion
87	        }
88	
89	        guard let data = try? JSONSerialization.data(withJSONObject: payload),
90	              let task else { return }
91	
92	        task.send(.string(String(data: data, encoding: .utf8)!)) { _ in }
93	    }
94	
95	    // MARK: - Private
96	
97	    /// Whether to try the tailscale host on next connection attempt.
98	    private var useTailscale = false
99	
100	    private func startConnection() {
101	        let host: String
102	        if useTailscale, let tsHost = credentials.tailscaleHost, !tsHost.isEmpty {
103	            host = tsHost
104	        } else {
105	            host = credentials.host
106	        }
107	
108	        let urlString = "ws://\(host):\(credentials.port)/ws"
109	        guard let url = URL(string: urlString) else { return }
110	
111	        var request = URLRequest(url: url)
112	        request.setValue("Bearer \(credentials.token)", forHTTPHeaderField: "Authorization")
113	        request.timeoutInterval = useTailscale ? 10 : 5
114	
115	        let session = URLSession(configuration: .default, delegate: self, delegateQueue: nil)
116	        self.session = session
117	        let task = session.webSocketTask(with: request)
118	        self.task = task
119	        task.resume()
120	        receiveNext()
121	    }
122	
123	    private func receiveNext() {
124	        task?.receive { [weak self] result in
125	            guard let self else { return }
126	            switch result {
127	            case .success(let message):
128	                self.handleMessage(message)
129	                self.receiveNext()
130	            case .failure:
131	                self.handleDisconnect(error: nil)
132	            }
133	        }
134	    }
135	
136	    private func handleMessage(_ message: URLSessionWebSocketTask.Message) {
137	        guard case .string(let text) = message,
138	              let data = text.data(using: .utf8),
139	              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
140	        else { return }
141	
142	        let bridgeMessage = parse(json: json)
143	        Task { @MainActor in
144	            self.delegate?.clientDidReceiveMessage(self, message: bridgeMessage)
145	        }
146	
147	        // Dispatch command responses to completions
148	        if let id = json["id"] as? String,
149	           let completion = completions.removeValue(forKey: id),
150	           let result = json["result"] as? [String: Any] {
151	            Task { @MainActor in completion(result) }
152	        }
153	    }
154	
155	    private func parse(json: [String: Any]) -> BridgeMessage {
156	        let type = json["type"] as? String ?? ""
157	        let data = json["data"] as? [String: Any] ?? [:]
158	
159	        switch type {
160	        case "connected":
161	            if let payloadData = try? JSONSerialization.data(withJSONObject: data),
162	               let payload = try? JSONDecoder().decode(ConnectedPayload.self, from: payloadData) {
163	                return .connected(payload)
164	            }
165	        case "notification.created":
166	            if let notifData = try? JSONSerialization.data(withJSONObject: data),
167	               let notif = try? JSONDecoder().decode(BridgeNotification.self, from: notifData) {
168	                return .notificationCreated(notif)
169	            }
170	        case "notification.cleared":
171	            return .notificationCleared
172	        case "cmux.connected":
173	            return .cmuxConnected
174	        case "cmux.disconnected":
175	            return .cmuxDisconnected
176	        default:
177	            break
178	        }
179	
180	        // Command response envelope
181	        if let id = json["id"] as? String {
182	            let ok = json["ok"] as? Bool ?? false
183	            let result = json["result"] as? [String: Any] ?? [:]
184	            var cmdError: CommandError?
185	            if let errDict = json["error"] as? [String: Any] {
186	                cmdError = CommandError(
187	                    code: errDict["code"] as? String ?? "",
188	                    message: errDict["message"] as? String ?? ""
189	                )
190	            }
191	            return .commandResponse(CommandResponse(id: id, ok: ok, result: result, error: cmdError))
192	        }
193	
194	        return .notificationCleared // fallback
195	    }
196	
197	    private func handleDisconnect(error: Error?) {
198	        task = nil
199	        Task { @MainActor in
200	            self.delegate?.clientDidDisconnect(self, error: error)
201	        }
202	        guard shouldReconnect else { return }
203	        scheduleReconnect()
204	    }
205	
206	    private func scheduleReconnect() {
207	        let delay = backoff
208	        backoff = min(backoff * 2, 30)
209	
210	        // Alternate between LAN and Tailscale on each retry
211	        if credentials.tailscaleHost != nil {
212	            useTailscale.toggle()
213	        }
214	
215	        reconnectTask = Task {
216	            try? await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
217	            guard !Task.isCancelled, self.shouldReconnect else { return }
218	            self.startConnection()
219	        }
220	    }
221	}
