// MARK: - Control keys

private var controlKeyRow: some View {
    ScrollView(.horizontal, showsIndicators: false) {
        HStack(spacing: 6) {
            ForEach(controlKeys, id: \.1) { label, key in
                controlChip(label: label, key: key)
            }
        }
        .padding(.horizontal, 2)
    }
